const errorInfo = $input.first().json.execution?.error || {};
const workflow = $input.first().json.workflow || {};
const execution = $input.first().json.execution || {};

const errorMessage = errorInfo.message || 'Unknown execution error';
const httpCode = errorInfo.httpCode || errorInfo.status || null;

// Clasificación: transitorio vs permanente
let isTransient = false;
if (httpCode === 429 || httpCode === 503 || httpCode === 504 || errorMessage.includes('timeout') || errorMessage.includes('ECONNRESET')) {
  isTransient = true;
}

// Extraer correlationId si venía en los datos de entrada
let correlationId = 'unknown';
try {
  const lastNodeData = execution.data?.resultData?.runData;
  if (lastNodeData) {
    const firstKey = Object.keys(lastNodeData)[0];
    const firstItem = lastNodeData[firstKey]?.[0]?.data?.main?.[0]?.[0]?.json;
    if (firstItem && firstItem.correlationId) {
      correlationId = firstItem.correlationId;
    } else if (firstItem?.event?.correlationId) {
      correlationId = firstItem.event.correlationId;
    }
  }
} catch (e) {
  // Continuar con fallback
}

const sanitizedReport = {
  operationId: 'err_' + Date.now(),
  correlationId,
  workflowId: workflow.id || 'unknown',
  workflowName: workflow.name || 'unknown',
  executionId: execution.id || 'unknown',
  errorType: isTransient ? 'transient' : 'permanent',
  errorMessage: errorMessage.replace(/key=[^&\s]+/gi, 'key=REDACTED'),
  httpCode,
  timestamp: new Date().toISOString()
};

return [{
  json: sanitizedReport
}];

const crypto = require('crypto');
const input = $input.first().json;
const secret = $env.RAX_N8N_SHARED_SECRET;
if (!secret) throw new Error('RAX_N8N_SHARED_SECRET is not configured');
const callbackPayload = {
  operationId: input.operationId || 'err_' + Date.now(),
  correlationId: input.correlationId || 'unknown',
  workflowId: input.workflowName || 'unknown',
  workflowVersion: '1.0.0',
  status: 'failed',
  error: {
    code: input.errorType || 'unknown',
    message: input.errorMessage || 'Unknown execution error',
    recoverable: input.errorType === 'transient',
    providerStatus: input.httpCode || null
  }
};
const timestamp = Math.floor(Date.now() / 1000).toString();
const callbackBody = JSON.stringify(callbackPayload);
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + callbackBody).digest('hex');
return [{ json: { ...input, callbackPayload, callbackBody, callbackTimestamp: timestamp, callbackSignature: signature, callbackCorrelationId: callbackPayload.correlationId } }];
